record.field:

# Default to the standard action
action = env.ref('account_reports.action_account_report_pl').read()[0]

if env.company.enable_insurance_pnl_format:
    custom_report = env.ref('insurance_profit_and_loss.insurance_profit_and_loss', raise_if_not_found=False)
